        "landing.howItWorks.step1.desc": "O cadastro leva poucos minutos: informe o horário de funcionamento, lista de preços e FAQ do seu negócio, depois conecte sua conta do Instagram Business com um clique (login seguro do Instagram, sem compartilhar senhas conosco).",
