        "landing.howItWorks.step1.title": "Verbinde dein Instagram",
        "landing.howItWorks.step1.desc": "Die Registrierung dauert nur wenige Minuten: Gib die Öffnungszeiten, Preisliste und FAQ deines Unternehmens ein und verbinde dann dein Instagram-Business-Konto mit einem Klick (sicherer Instagram-Login, keine Passwörter werden mit uns geteilt).",
        "landing.howItWorks.step2.title": "Die KI verfasst Antworten",
        "landing.howItWorks.step2.desc": "Jede neue Kunden-DM wird von der KI gelesen, die sofort eine Antwort verfasst — präzise, höflich und in der Sprache des Kunden, basierend auf den Daten deines Unternehmens.",
        "landing.howItWorks.step3.title": "Du genehmigst und sendest",
        "landing.howItWorks.step3.desc": "Vorschläge warten im Dashboard auf dich. Prüfen, bei Bedarf anpassen, klicken — und die Antwort erreicht den Kunden. Standardmäßig behältst du die Kontrolle, mit optionalem Auto-Senden für sofortige Antworten.",
        "landing.whoFor.title": "Für jedes Unternehmen, das in seinem Posteingang lebt",
