        "privacy.title": "Gizlilik Politikası",
        "privacy.updated": "Son güncelleme: 15 Temmuz 2026.",
        "privacy.intro": "Bu politika, Camilius'un hangi verileri, neden topladığını ve nasıl sakladığını açıklar. Hizmet şu anda Mihajlo Savovic tarafından bireysel olarak işletilmektedir (not: hizmet bir şirket olarak kaydedilirse bu güncellenecektir).",
        "privacy.contact.heading": "İletişim",
        "privacy.contact.body": "Gizlilikle ilgili sorularınız veya veri erişim/silme talepleriniz için şu adrese yazın:",
        "privacy.dataCollected.heading": "Hangi verileri topluyoruz",
        "privacy.dataCollected.intro": "İşletme sahibinden, kayıt sırasında:",
        "privacy.dataCollected.item1": "İşletme adı, kullanıcı adı ve şifre (şifre karma olarak saklanır, asla okunabilir biçimde değil)",
        "privacy.dataCollected.item2": "Yalnızca hesap kurtarma (şifre sıfırlama) ve önemli hesap bildirimleri için kullanılan bir iletişim e-postası",
        "privacy.dataCollected.item3": "Girdiğiniz çalışma saatleri, fiyat listesi ve SSS",
        "privacy.dataCollected.instagram": "Instagram Business hesabınızı bağladığınızda, hizmetin sizin adınıza hesabınızın direkt mesajlarını okumasını ve yanıtlamasını sağlayan bir erişim belirteci (Instagram'ın resmi Business Login/OAuth akışı üzerinden) alır ve saklarız. Hizmeti sunmanın bir parçası olarak, sistem ayrıca bağlı hesabınıza gelen Instagram mesajlarının içeriğini (müşterilerinizin sorularını) önerilen yanıtlar oluşturmak için okur ve yanıtların doğru kişiye gönderilebilmesi için gönderenin Instagram'a özgü tanımlayıcısını ve (mevcutsa) kullanıcı adını saklar.",
        "privacy.why.heading": "Bu verileri neden topluyoruz",
        "privacy.why.body": "Yalnızca hizmetin işlevini sağlamak için: Instagram üzerinden gönderilen müşteri sorularını otomatik olarak okumak ve işletmenizin verilerine dayalı yanıtlar önermek. Varsayılan olarak, gönderilmeden önce her yanıtı manuel olarak gözden geçirir ve onaylarsınız; isterseniz Ayarlar'dan otomatik göndermeyi etkinleştirebilirsiniz, bu durumda yanıtlar manuel inceleme olmadan gönderilir.",
        "privacy.sharing.heading": "Verileri kimlerle paylaşıyoruz",
